428|char *json_dumps(const json_t *json, size_t flags) {
429|    strbuffer_t strbuff;
430|    char *result;
431|
432|    if (strbuffer_init(&strbuff))
433|        return NULL;
434|
435|    if (json_dump_callback(json, dump_to_strbuffer, (void *)&strbuff, flags))
436|        result = NULL;
437|    else {
438|        char *new_result;
439|        result = strbuffer_steal_value(&strbuff);
440|        // technically the resizing is not needed.
441|        new_result = jsonp_realloc(result, strbuff.size, strbuff.length + 1);
442|        if (new_result) { // when realloc fails we just use the original pointer
443|            result = new_result;
444|        }
445|    }
446|
447|    strbuffer_close(&strbuff);
448|    return result;
449|}

