39|void *jsonp_realloc(void *ptr, size_t originalSize, size_t newSize) {
40|    void *newMemory;
41|
42|    if (do_realloc)
43|        return (*do_realloc)(ptr, newSize);
44|
45|    // realloc emulation using malloc and free
46|    if (newSize == 0) {
47|        if (ptr != NULL)
48|            (*do_free)(ptr);
49|
50|        return NULL;
51|    } else {
52|        newMemory = (*do_malloc)(newSize);
53|
54|        if ((newMemory != NULL) && (ptr != NULL)) {
55|            memcpy(newMemory, ptr, (originalSize < newSize) ? originalSize : newSize);
56|
57|            (*do_free)(ptr);
58|        }
59|
60|        return newMemory;
61|    }
62|}

