60|int strbuffer_append_bytes(strbuffer_t *strbuff, const char *data, size_t size) {
61|    if (size >= strbuff->size - strbuff->length) {
62|        size_t new_size;
63|        char *new_value;
64|
65|        /* avoid integer overflow */
66|        if (strbuff->size > STRBUFFER_SIZE_MAX / STRBUFFER_FACTOR ||
67|            size > STRBUFFER_SIZE_MAX - 1 ||
68|            strbuff->length > STRBUFFER_SIZE_MAX - 1 - size)
69|            return -1;
70|
71|        new_size = max(strbuff->size * STRBUFFER_FACTOR, strbuff->length + size + 1);
72|
73|        new_value = jsonp_realloc(strbuff->value, strbuff->size, new_size);
74|        if (!new_value)
75|            return -1;
76|
77|        strbuff->value = new_value;
78|        strbuff->size = new_size;
79|    }
80|
81|    memcpy(strbuff->value + strbuff->length, data, size);
82|    strbuff->length += size;
83|    strbuff->value[strbuff->length] = '\0';
84|
85|    return 0;
86|}

