896|int json_vunpack_ex(json_t *root, json_error_t *error, size_t flags, const char *fmt,
897|                    va_list ap) {
898|    scanner_t s;
899|    va_list ap_copy;
900|
901|    if (!root) {
902|        jsonp_error_init(error, "<root>");
903|        jsonp_error_set(error, -1, -1, 0, json_error_null_value, "NULL root value");
904|        return -1;
905|    }
906|
907|    if (!fmt || !*fmt) {
908|        jsonp_error_init(error, "<format>");
909|        jsonp_error_set(error, -1, -1, 0, json_error_invalid_argument,
910|                        "NULL or empty format string");
911|        return -1;
912|    }
913|    jsonp_error_init(error, NULL);
914|
915|    scanner_init(&s, error, flags, fmt);
916|    next_token(&s);
917|
918|    va_copy(ap_copy, ap);
919|    if (unpack(&s, root, &ap_copy, NULL)) {
920|        va_end(ap_copy);
921|        return -1;
922|    }
923|    va_end(ap_copy);
924|
925|    next_token(&s);
926|    if (token(&s)) {
927|        set_error(&s, "<format>", json_error_invalid_format,
928|                  "Garbage after format string");
929|        return -1;
930|    }
931|
932|    return 0;
933|}

473|static int unpack_object(scanner_t *s, json_t *root, va_list *ap,
474|                         const char *parent_key) {
475|    int ret = -1;
476|    int strict = 0;
477|    int gotopt = 0;
478|
479|    /* Use a set (emulated by a hashtable) to check that all object
480|       keys are accessed. Checking that the correct number of keys
481|       were accessed is not enough, as the same key can be unpacked
482|       multiple times.
483|    */
484|    hashtable_t key_set;
485|
486|    if (hashtable_init(&key_set)) {
487|        set_error(s, "<internal>", json_error_out_of_memory, "Out of memory");
488|        return -1;
489|    }
490|
491|    if (root && !json_is_object(root)) {
492|        set_error(s, "<validation>", json_error_wrong_type, "Expected object, got %s%s%s",
493|                  type_name(root), parent_key ? " for key " : "",
494|                  parent_key ? parent_key : "");
495|        goto out;
496|    }
497|    next_token(s);
498|
499|    while (token(s) != '}') {
500|        const char *key;
501|        size_t key_len;
502|        json_t *value;
503|        int opt = 0;
504|
505|        if (strict != 0) {
506|            set_error(s, "<format>", json_error_invalid_format,
507|                      "Expected '}' after '%c', got '%c'", (strict == 1 ? '!' : '*'),
508|                      token(s));
509|            goto out;
510|        }
511|
512|        if (!token(s)) {
513|            set_error(s, "<format>", json_error_invalid_format,
514|                      "Unexpected end of format string");
515|            goto out;
516|        }
517|
518|        if (token(s) == '!' || token(s) == '*') {
519|            strict = (token(s) == '!' ? 1 : -1);
520|            next_token(s);
521|            continue;
522|        }
523|
524|        if (token(s) != 's') {
525|            set_error(s, "<format>", json_error_invalid_format,
526|                      "Expected format 's', got '%c'", token(s));
527|            goto out;
528|        }
529|
530|        key = va_arg(*ap, const char *);
531|        if (!key) {
532|            set_error(s, "<args>", json_error_null_value, "NULL object key");
533|            goto out;
534|        }
535|        key_len = strlen(key);
536|
537|        next_token(s);
538|
539|        if (token(s) == '?') {
540|            opt = gotopt = 1;
541|            next_token(s);
542|        }
543|
544|        if (!root) {
545|            /* skipping */
546|            value = NULL;
547|        } else {
548|            value = json_object_getn(root, key, key_len);
549|            if (!value && !opt) {
550|                set_error(s, "<validation>", json_error_item_not_found,
551|                          "Object item not found: %s", key);
552|                goto out;
553|            }
554|        }
555|
556|        if (unpack(s, value, ap, key))
557|            goto out;
558|
559|        hashtable_set(&key_set, key, key_len, json_null());
560|        next_token(s);
561|    }
562|
563|    if (strict == 0 && (s->flags & JSON_STRICT))
564|        strict = 1;
565|
566|    if (root && strict == 1) {
567|        /* We need to check that all non optional items have been parsed */
568|        const char *key;
569|        size_t key_len;
570|        /* keys_res is 1 for uninitialized, 0 for success, -1 for error. */
571|        int keys_res = 1;
572|        strbuffer_t unrecognized_keys;
573|        json_t *value;
574|        long unpacked = 0;
575|
576|        if (gotopt || json_object_size(root) != key_set.size) {
577|            json_object_keylen_foreach(root, key, key_len, value) {
578|                if (!hashtable_get(&key_set, key, key_len)) {
579|                    unpacked++;
580|
581|                    /* Save unrecognized keys for the error message */
582|                    if (keys_res == 1) {
583|                        keys_res = strbuffer_init(&unrecognized_keys);
584|                    } else if (!keys_res) {
585|                        keys_res = strbuffer_append_bytes(&unrecognized_keys, ", ", 2);
586|                    }
587|
588|                    if (!keys_res)
589|                        keys_res =
590|                            strbuffer_append_bytes(&unrecognized_keys, key, key_len);
591|                }
592|            }
593|        }
594|        if (unpacked) {
595|            set_error(s, "<validation>", json_error_end_of_input_expected,
596|                      "%li object item(s) left unpacked: %s", unpacked,
597|                      keys_res ? "<unknown>" : strbuffer_value(&unrecognized_keys));
