686|
687|        case '[':
688|            return unpack_array(s, root, ap, key);
689|
690|        case 's':
691|            if (root && !json_is_string(root)) {
692|                set_error(s, "<validation>", json_error_wrong_type,
693|                          "Expected string, got %s%s%s", type_name(root),
694|                          key ? " for key " : "", key ? key : "");
695|                return -1;
696|            }
697|
698|            if (!(s->flags & JSON_VALIDATE_ONLY)) {
699|                const char **str_target;
700|                size_t *len_target = NULL;
701|
702|                str_target = va_arg(*ap, const char **);
703|                if (!str_target) {
704|                    set_error(s, "<args>", json_error_null_value, "NULL string argument");
705|                    return -1;
706|                }
707|
708|                next_token(s);
709|
710|                if (token(s) == '%') {
711|                    len_target = va_arg(*ap, size_t *);
