713|                        set_error(s, "<args>", json_error_null_value,
714|                                  "NULL string length argument");
715|                        return -1;
716|                    }
717|                } else
718|                    prev_token(s);
719|
720|                if (root) {
721|                    *str_target = json_string_value(root);
722|                    if (len_target)
723|                        *len_target = json_string_length(root);
724|                }
725|            }
726|            return 0;
727|
728|        case 'i':
729|            if (root && !json_is_integer(root)) {
730|                set_error(s, "<validation>", json_error_wrong_type,
731|                          "Expected integer, got %s%s%s", type_name(root),
732|                          key ? " for key " : "", key ? key : "");
733|                return -1;
734|            }
735|
736|            if (!(s->flags & JSON_VALIDATE_ONLY)) {
737|                int *target = va_arg(*ap, int *);
738|                if (root)
739|                    *target = (int)json_integer_value(root);
740|            }
741|
742|            return 0;
743|
744|        case 'I':
745|            if (root && !json_is_integer(root)) {
746|                set_error(s, "<validation>", json_error_wrong_type,
747|                          "Expected integer, got %s%s%s", type_name(root),
748|                          key ? " for key " : "", key ? key : "");
749|                return -1;
750|            }
751|
752|            if (!(s->flags & JSON_VALIDATE_ONLY)) {
753|                json_int_t *target = va_arg(*ap, json_int_t *);
754|                if (root)
755|                    *target = json_integer_value(root);
756|            }
757|
758|            return 0;
759|
760|        case 'b':
761|            if (root && !json_is_boolean(root)) {
762|                set_error(s, "<validation>", json_error_wrong_type,
763|                          "Expected true or false, got %s%s%s", type_name(root),
764|                          key ? " for key " : "", key ? key : "");
765|                return -1;
766|            }
767|
768|            if (!(s->flags & JSON_VALIDATE_ONLY)) {
769|                int *target = va_arg(*ap, int *);
770|                if (root)
771|                    *target = json_is_true(root);
772|            }
773|
774|            return 0;
775|
776|        case 'f':
777|            if (root && !json_is_real(root)) {
778|                set_error(s, "<validation>", json_error_wrong_type,
779|                          "Expected real, got %s%s%s", type_name(root),
780|                          key ? " for key " : "", key ? key : "");
781|                return -1;
782|            }
783|
784|            if (!(s->flags & JSON_VALIDATE_ONLY)) {
785|                double *target = va_arg(*ap, double *);
786|                if (root)
787|                    *target = json_real_value(root);
788|            }
789|
790|            return 0;
791|
792|        case 'F':
793|            if (root && !json_is_number(root)) {
794|                set_error(s, "<validation>", json_error_wrong_type,
795|                          "Expected real or integer, got %s%s%s", type_name(root),
796|                          key ? " for key " : "", key ? key : "");
797|                return -1;
798|            }
799|
800|            if (!(s->flags & JSON_VALIDATE_ONLY)) {
801|                double *target = va_arg(*ap, double *);
802|                if (root)
803|                    *target = json_number_value(root);
804|            }
805|
806|            return 0;
807|
808|        case 'O':
809|            if (root && !(s->flags & JSON_VALIDATE_ONLY))
