31|extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
32|{
33|  json_error_t error;
34|  unsigned char dump_mode;
35|
36|  // Enable or disable diagnostics based on the FUZZ_VERBOSE environment flag.
37|  enable_diags = (getenv("FUZZ_VERBOSE") != NULL);
38|
39|  FUZZ_DEBUG("Input data length: %zd", size);
40|
41|  if (size < NUM_COMMAND_BYTES)
42|  {
43|    return 0;
44|  }
45|
46|  // Use the first sizeof(size_t) bytes as load flags.
47|  size_t load_flags = *(const size_t*)data;
48|  data += sizeof(size_t);
49|
50|  FUZZ_DEBUG("load_flags: 0x%zx\n"
51|             "& JSON_REJECT_DUPLICATES =  0x%zx\n"
52|             "& JSON_DECODE_ANY =         0x%zx\n"
53|             "& JSON_DISABLE_EOF_CHECK =  0x%zx\n"
54|             "& JSON_DECODE_INT_AS_REAL = 0x%zx\n"
55|             "& JSON_ALLOW_NUL =          0x%zx\n",
56|             load_flags,
57|             load_flags & JSON_REJECT_DUPLICATES,
58|             load_flags & JSON_DECODE_ANY,
59|             load_flags & JSON_DISABLE_EOF_CHECK,
60|             load_flags & JSON_DECODE_INT_AS_REAL,
61|             load_flags & JSON_ALLOW_NUL);
62|
63|  // Use the next sizeof(size_t) bytes as dump flags.
64|  size_t dump_flags = *(const size_t*)data;
65|  data += sizeof(size_t);
66|
67|  FUZZ_DEBUG("dump_flags: 0x%zx\n"
68|             "& JSON_MAX_INDENT =     0x%zx\n"
69|             "& JSON_COMPACT =        0x%zx\n"
70|             "& JSON_ENSURE_ASCII =   0x%zx\n"
71|             "& JSON_SORT_KEYS =      0x%zx\n"
72|             "& JSON_PRESERVE_ORDER = 0x%zx\n"
73|             "& JSON_ENCODE_ANY =     0x%zx\n"
74|             "& JSON_ESCAPE_SLASH =   0x%zx\n"
75|             "& JSON_REAL_PRECISION = 0x%zx\n"
76|             "& JSON_EMBED =          0x%zx\n",
77|             dump_flags,
78|             dump_flags & JSON_MAX_INDENT,
79|             dump_flags & JSON_COMPACT,
80|             dump_flags & JSON_ENSURE_ASCII,
81|             dump_flags & JSON_SORT_KEYS,
82|             dump_flags & JSON_PRESERVE_ORDER,
83|             dump_flags & JSON_ENCODE_ANY,
84|             dump_flags & JSON_ESCAPE_SLASH,
85|             ((dump_flags >> 11) & 0x1F) << 11,
86|             dump_flags & JSON_EMBED);
87|
88|  // Use the next byte as the dump mode.
89|  dump_mode = data[0];
90|  data++;
91|
92|  FUZZ_DEBUG("dump_mode: 0x%x", (unsigned int)dump_mode);
93|
94|  // Remove the command bytes from the size total.
95|  size -= NUM_COMMAND_BYTES;
96|
97|  // Attempt to load the remainder of the data with the given load flags.
98|  const char* text = reinterpret_cast<const char *>(data);
99|  json_t* jobj = json_loadb(text, size, load_flags, &error);
100|
101|  if (jobj == NULL)
102|  {
103|    return 0;
104|  }
105|
106|  if (dump_mode & FUZZ_DUMP_STRING)
107|  {
108|    // Dump as a string. Remove indents so that we don't run out of memory.
109|    char *out = json_dumps(jobj, dump_flags & ~JSON_MAX_INDENT);
110|    if (out != NULL)
111|    {
112|      free(out);
113|    }
114|  }
115|  else
116|  {
117|    // Default is callback mode.
118|    //
119|    // Attempt to dump the loaded json object with the given dump flags.
120|    uint64_t counter = 0;
121|
122|    json_dump_callback(jobj, json_dump_counter, &counter, dump_flags);
123|    FUZZ_DEBUG("Counter function counted %" PRIu64 " bytes.", counter);
124|  }
125|
126|  if (jobj)
127|  {
128|    json_decref(jobj);
129|  }
130|
131|  return 0;
132|}

850|static json_t *parse_json(lex_t *lex, size_t flags, json_error_t *error) {
851|    json_t *result;
852|
853|    lex->depth = 0;
854|
855|    lex_scan(lex, error);
856|    if (!(flags & JSON_DECODE_ANY)) {
857|        if (lex->token != '[' && lex->token != '{') {
858|            error_set(error, lex, json_error_invalid_syntax, "'[' or '{' expected");
859|            return NULL;
860|        }
861|    }
862|
863|    result = parse_value(lex, flags, error);
864|    if (!result)
865|        return NULL;
866|
867|    if (!(flags & JSON_DISABLE_EOF_CHECK)) {
868|        lex_scan(lex, error);
869|        if (lex->token != TOKEN_EOF) {
870|            error_set(error, lex, json_error_end_of_input_expected,
871|                      "end of file expected");
872|            json_decref(result);
873|            return NULL;
874|        }
875|    }
876|
877|    if (error) {
878|        /* Save the position even though there was no error */
879|        error->position = (int)lex->stream.position;
880|    }
881|
882|    return result;
883|}

85|static void error_set(json_error_t *error, const lex_t *lex, enum json_error_code code,
86|                      const char *msg, ...) {
87|    va_list ap;
88|    char msg_text[JSON_ERROR_TEXT_LENGTH];
89|    char msg_with_context[JSON_ERROR_TEXT_LENGTH];
90|
91|    int line = -1, col = -1;
92|    size_t pos = 0;
93|    const char *result = msg_text;
94|
95|    if (!error)
96|        return;
97|
98|    va_start(ap, msg);
99|    vsnprintf(msg_text, JSON_ERROR_TEXT_LENGTH, msg, ap);
100|    msg_text[JSON_ERROR_TEXT_LENGTH - 1] = '\0';
101|    va_end(ap);
102|
103|    if (lex) {
104|        const char *saved_text = strbuffer_value(&lex->saved_text);
105|
106|        line = lex->stream.line;
107|        col = lex->stream.column;
108|        pos = lex->stream.position;
109|
110|        if (saved_text && saved_text[0]) {
111|            if (lex->saved_text.length <= 20) {
112|                snprintf(msg_with_context, JSON_ERROR_TEXT_LENGTH, "%s near '%s'",
113|                         msg_text, saved_text);
114|                msg_with_context[JSON_ERROR_TEXT_LENGTH - 1] = '\0';
115|                result = msg_with_context;
116|            }
117|        } else {
118|            if (code == json_error_invalid_syntax) {
119|                /* More specific error code for premature end of file. */
120|                code = json_error_premature_end_of_input;
121|            }
122|            if (lex->stream.state == STREAM_STATE_ERROR) {
123|                /* No context for UTF-8 decoding errors */
124|                result = msg_text;
125|            } else {
126|                snprintf(msg_with_context, JSON_ERROR_TEXT_LENGTH, "%s near end of file",
127|                         msg_text);
128|                msg_with_context[JSON_ERROR_TEXT_LENGTH - 1] = '\0';
129|                result = msg_with_context;
130|            }
131|        }
132|    }
133|
134|    jsonp_error_set(error, line, col, pos, code, "%s", result);
