58|static void next_token(scanner_t *s) {
59|    const char *t;
60|    s->prev_token = s->token;
61|
62|    if (s->next_token.line) {
63|        s->token = s->next_token;
64|        s->next_token.line = 0;
65|        return;
66|    }
67|
68|    if (!token(s) && !*s->fmt)
69|        return;
70|
71|    t = s->fmt;
72|    s->column++;
73|    s->pos++;
74|
75|    /* skip space and ignored chars */
76|    while (*t == ' ' || *t == '\t' || *t == '\n' || *t == ',' || *t == ':') {
77|        if (*t == '\n') {
78|            s->line++;
79|            s->column = 1;
80|        } else
81|            s->column++;
82|
83|        s->pos++;
84|        t++;
85|    }
86|
87|    s->token.token = *t;
88|    s->token.line = s->line;
89|    s->token.column = s->column;
90|    s->token.pos = s->pos;
91|
92|    if (*t)
