135|        if (!str) {
136|            if (!optional) {
137|                set_error(s, "<args>", json_error_null_value, "NULL %s", purpose);
138|                s->has_error = 1;
139|            }
140|            return NULL;
141|        }
142|
143|        length = strlen(str);
