163|        s->has_error = 1;
164|    }
165|
166|    while (1) {
167|        str = va_arg(*ap, const char *);
168|        if (!str) {
169|            set_error(s, "<args>", json_error_null_value, "NULL %s", purpose);
170|            s->has_error = 1;
171|        }
