209|    if (!utf8_check_string(strbuff.value, strbuff.length)) {
210|        set_error(s, "<args>", json_error_invalid_utf8, "Invalid UTF-8 %s", purpose);
211|        strbuffer_close(&strbuff);
212|        s->has_error = 1;
213|        return NULL;
